CREATE TABLE documents (id BIGINT NOT NULL AUTO_INCREMENT,workspace_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,content LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),INDEX idx_documents_workspace_id(workspace_id),INDEX idx_documents_workspace_status(workspace_id,status),CONSTRAINT fk_documents_workspace FOREIGN KEY(workspace_id) REFERENCES workspaces(id),CONSTRAINT fk_documents_created_by FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
